// ScopedProductListing 一件商品在某个作用域（大区或门店）下的可见性与生效价。
// `GET /admin/stores/{store_id}/products` 与
// `GET /admin/regions/{region_id}/products` 共用这一个形状。
type ScopedProductListing struct {
	// EffectiveListed 两层都算完之后买家到底看不看得见。
	//
	// **与 `listed` 刻意分开**：一件被大区排掉的商品，门店这一层设成
	// `listed = true` 也捞不回来（两层是**与**不是**或**）。
	// 合成一个字段的话，后台会显示「已上架」而买家看不到，
	// 而那种不一致没有任何东西会报出来。
	EffectiveListed bool    `json:"effective_listed"`
	ImageUrl        *string `json:"image_url,omitempty"`

	// Listed **本作用域**有没有把它下架。`true` 表示这一层没有排除它——
	// 也就是 `store_product_overrides` / `region_product_overrides`
	// 里**没有**那一行（缺一行即在售，数据模型 §4）。
	Listed bool `json:"listed"`

	// MaxPriceCents 最大值。
	MaxPriceCents *Money `json:"max_price_cents,omitempty"`

	// MinPriceCents 本作用域下这件商品各 SKU 生效价的最小值。
	MinPriceCents *Money `json:"min_price_cents,omitempty"`

	// PriceSource 这个价来自哪一层：**1 基准价 / 2 大区价 / 3 门店价**。
	// 取自 `sku_prices_by_store` 视图——全仓库唯一一处写
	// `COALESCE(门店价, 大区价, 基准价)` 的地方（数据模型 §4）。
	//
	// 一件商品的多个 SKU 可能落在不同层上，此时取**最内的那一层**
	// （有任何一个 SKU 用了门店价就是 3）——它回答的是
	// 「这一行有没有被本地覆盖过」，运营要按它筛。
	PriceSource ScopedProductListingPriceSource `json:"price_source"`
	ProductId   int64                           `json:"product_id"`

	// Status 租户级的 `products.status`：0 草稿 / 1 上架 / 2 下架。
	Status *ScopedProductListingStatus `json:"status,omitempty"`
	Title  string                      `json:"title"`
}

// ScopedProductListingPriceSource 这个价来自哪一层：**1 基准价 / 2 大区价 / 3 门店价**。
// 取自 `sku_prices_by_store` 视图——全仓库唯一一处写
// `COALESCE(门店价, 大区价, 基准价)` 的地方（数据模型 §4）。
//
// 一件商品的多个 SKU 可能落在不同层上，此时取**最内的那一层**
// （有任何一个 SKU 用了门店价就是 3）——它回答的是
// 「这一行有没有被本地覆盖过」，运营要按它筛。
type ScopedProductListingPriceSource int

// ScopedProductListingStatus 租户级的 `products.status`：0 草稿 / 1 上架 / 2 下架。
type ScopedProductListingStatus int

// ScopedSkuPrice 一个 SKU 在某个作用域（大区或门店）下的价格覆盖与生效价。
type ScopedSkuPrice struct {
	// BasePriceCents `skus.price_cents`，最外层的基准价。
	BasePriceCents *Money `json:"base_price_cents,omitempty"`

	// EffectivePriceCents 三层 `COALESCE` 之后真正生效的价。
	EffectivePriceCents Money `json:"effective_price_cents"`

	// OverridePriceCents **本作用域**自己定的价。为 null 表示这一层没有覆盖，
	// 沿用上一层——那正是这两张表「缺一行即继承」的语义
	// （数据模型 §4）。撤销覆盖走 `DELETE`，不是把它设成 null。
	OverridePriceCents *int64 `json:"override_price_cents,omitempty"`

	// PriceSource 1 基准价 / 2 大区价 / 3 门店价。
	PriceSource ScopedSkuPricePriceSource `json:"price_source"`
	SkuCode     *string                   `json:"sku_code,omitempty"`
	SkuId       int64                     `json:"sku_id"`
}

// ScopedSkuPricePriceSource 1 基准价 / 2 大区价 / 3 门店价。
type ScopedSkuPricePriceSource int

// SearchFilters defines model for SearchFilters.
type SearchFilters struct {
	CategoryId *int64 `json:"category_id,omitempty"`

	// InStockOnly 只要当前门店有货的。**默认值本轮从 `true` 改成 `false`**，
	// 与 `GET /products?in_stock_only=` 对齐（M3 独立验收 I10）。
	//
	// 改的不只是为了一致：契约原先把同一件事写了两遍且互相矛盾——
	// `/search` 的描述写着业务重排会把缺货商品**降权**，
	// 而这个默认值说的是**删掉**。两者并存时默认值那一份赢，
	// 于是「降权」那句话从来没被执行过。
	//
	// 注意这个开关**管不到「这家店卖不卖」**：门店与大区的上下架是
	// 可见性本身，无条件生效、关不掉（数据模型 §4）。
	InStockOnly *bool `json:"in_stock_only,omitempty"`

	// MaxPriceCents 同上。
	MaxPriceCents *Money `json:"max_price_cents,omitempty"`

	// MinPriceCents 按**当前门店的生效价**过滤（三层 `COALESCE` 之后的值），
	// 不是按基准价。`products.min_price_cents` / `max_price_cents`
	// 两列本轮已从数据模型里删掉——三层定价之后它们不再是商品的属性
	// （数据模型 §3 / §4）。
	MinPriceCents *Money `json:"min_price_cents,omitempty"`
}

// SearchHit defines model for SearchHit.
type SearchHit struct {
	Id       int64   `json:"id"`
	ImageUrl *string `json:"image_url,omitempty"`

	// InStock 这家店里任意一个在售 SKU 可售数 > 0。`GET /products` 与 `POST /search` 都按解析出的门店填
	// （2026-09-27 起列表也填；之前列表恒缺席，买家端因此无法在列表上标无货）。
	// **缺席**表示这一次不知道（拆分部署下库存服务不在），客户端不应据此判成无货。
	InStock *bool `json:"in_stock,omitempty"`

	// MaxPriceCents 金额，单位「分」。禁止使用浮点。
	MaxPriceCents *Money `json:"max_price_cents,omitempty"`

	// MinPriceCents 金额，单位「分」。禁止使用浮点。
	MinPriceCents Money `json:"min_price_cents"`

	// PromoMinPriceCents 这件商品在同一家门店此刻的最低活动单价（限时折扣 / 秒杀给出的各 SKU `Sku.promo_price_cents` 里最低的那个）。
	// **只在它低于 `min_price_cents` 时出现**；没有单价类活动、或特价只落在较贵的规格上时缺席。
	// 列表卡片用它显示活动价、把 `min_price_cents` 划线。`GET /products` 与 `POST /search` 都填
	// （2026-09-28 起；之前卡片只有门店价，要点进规格浮层才看得到特价）。
	PromoMinPriceCents *Money `json:"promo_min_price_cents,omitempty"`

	// PromotionTags 这件商品在响应里 `store` 那家门店**此刻生效**的活动标签（满减满折、限时折扣、秒杀）。
	// 没有活动时为空数组。`min_price_cents` 仍是门店价，不是活动价——活动价看标签与
	// `Sku.promo_price_cents`，最终以 `/orders/preview` 为准。
	PromotionTags *[]PromotionTag `json:"promotion_tags,omitempty"`

	// RecallSource 该结果来自哪一路召回，`explain=true` 时返回。
	// 调双路召回权重时这是第一手信息——某类查询长期只由单路命中，
	// 说明另一路在这类查询上失效了。
	RecallSource *SearchHitRecallSource `json:"recall_source,omitempty"`
	SalesCount   *int                   `json:"sales_count,omitempty"`

	// Scores explain=true 时返回，用于效果调优
	Scores *struct {
		Business *float32 `json:"business,omitempty"`
		Final    *float32 `json:"final,omitempty"`
		Keyword  *float32 `json:"keyword,omitempty"`
		Rerank   *float32 `json:"rerank,omitempty"`
		Rrf      *float32 `json:"rrf,omitempty"`
		Vector   *float32 `json:"vector,omitempty"`
	} `json:"scores,omitempty"`

	// Status 对应 `products.status`：0 草稿 / 1 上架 / 2 下架。
	// 前台列表与检索只返回 `1`；订单、购物车里引用的历史商品可能是 `2`，
	// 客户端据此展示「已下架」而不是让用户点进去才发现买不了。
	Status   SearchHitStatus `json:"status"`
	Subtitle *string         `json:"subtitle,omitempty"`
	Title    string          `json:"title"`
}

// SearchHitRecallSource 该结果来自哪一路召回，`explain=true` 时返回。
// 调双路召回权重时这是第一手信息——某类查询长期只由单路命中，
// 说明另一路在这类查询上失效了。
type SearchHitRecallSource string

// SearchHitStatus 对应 `products.status`：0 草稿 / 1 上架 / 2 下架。
// 前台列表与检索只返回 `1`；订单、购物车里引用的历史商品可能是 `2`，
// 客户端据此展示「已下架」而不是让用户点进去才发现买不了。
type SearchHitStatus int

// SearchRequest `POST /search` 的请求体。**本轮从内联 schema 提成具名的**——
// 内联的生成器不出类型，handler 只能手写绑定，这条刚在
// `PaymentCreateRequest` 和这个 `/search` 上踩过两次。
type SearchRequest struct {
	// Explain 返回各阶段得分，用于调试与效果评估
	Explain *bool          `json:"explain,omitempty"`
	Filters *SearchFilters `json:"filters,omitempty"`
	Query   string         `json:"query"`
	Size    *int           `json:"size,omitempty"`

	// StoreId 按哪家门店检索。与 `GET /products` 的同名查询参数逐字同义、
	// 同回落链（不传即走「默认门店 → 不在服务范围」那条链，
	// **不是**全租户并集）。
	//
	// 放在请求体顶层而不是 `filters` 里：`filters` 是**筛选条件**
	// （买家自己勾的），门店是**上下文**（服务端解析出来的）。
	// 混在一起会让「清空筛选」这个动作把门店也清掉。
	StoreId *int64 `json:"store_id,omitempty"`

	// Strategy 排序策略标识，用于 A/B 对比。记入检索日志后可按策略分组
	// 对比 NDCG@10 / CTR@10 等在线指标。省略则用默认策略。
	// 一期不做完整分流，但接口层先留出这个参数 ——
	// 否则后续每次改排序都是不可逆的「拍脑袋上线」
	// （语义检索层设计 §9.3）。
	//
	// 当前认得的两条（M5）：`rrf-biz-v1`（默认：双路召回 + RRF +
	// 业务重排）与 `rrf-v1`（双路召回 + RRF，不做业务重排，留作对照）。
	// 省略、`default` 或任何不认得的值都落到默认那条，**不报错**——
	// 响应里的 `strategy` 回显的是真正跑过的那一条，不是请求原文。
	// Reranker 精排还没有落地，没有任何策略包含它。
	Strategy *string `json:"strategy,omitempty"`
}

// Shipment defines model for Shipment.
type Shipment struct {
	// CarrierCode 承运商标识，如 sf / jd / yto
	CarrierCode string     `json:"carrier_code"`
	DeliveredAt *time.Time `json:"delivered_at,omitempty"`
	Id          int64      `json:"id"`
	ShippedAt   time.Time  `json:"shipped_at"`

	// Status 1 已发出 · 2 已签收 · 3 异常
	Status     ShipmentStatus `json:"status"`
	TrackingNo string         `json:"tracking_no"`
}

// ShipmentStatus 1 已发出 · 2 已签收 · 3 异常
type ShipmentStatus int

// ShipmentCreateRequest 一期不接受发货明细——整单发货，包裹内容即订单全部商品。
// 将来支持部分发货时在这里加 `items`，属于向后兼容的增量。
type ShipmentCreateRequest struct {
	CarrierCode string `json:"carrier_code"`
	TrackingNo  string `json:"tracking_no"`
}

// ShopSettings defines model for ShopSettings.
type ShopSettings struct {
	// AfterSaleDays 售后期：订单**完成**（确认收货）后多少天内可以申请售后，默认 15（2026-09-28 起）。
	// 过了之后申请回 409 `after-sale-window-closed`；还没完成的订单不受它限制。
	AfterSaleDays int `json:"after_sale_days"`

	// AutoConfirmDays 发货后多少天由系统自动确认收货
	AutoConfirmDays int `json:"auto_confirm_days"`

	// ReturnShipDays 退货退款审核通过后多少天未填寄回物流即自动关闭
	ReturnShipDays int `json:"return_ship_days"`

	// ServicePhone 客服电话；没设为 null
	ServicePhone *string `json:"service_phone"`

	// ShopName 店铺名称（只读，`merchants` 目录里的当前名称；由平台改）
	ShopName string `json:"shop_name"`

	// Timezone IANA 时区名。经营报表按它切自然日
	//
	// Examples: Asia/Shanghai
	Timezone string `json:"timezone"`

	// UpdatedAt 最近一次修改的时间；从没改过（全是默认值）为 null
	UpdatedAt *time.Time `json:"updated_at"`
}

// ShopSettingsInput defines model for ShopSettingsInput.
type ShopSettingsInput struct {
	// AfterSaleDays 售后期（完成后多少天内可申请售后）。不给即默认 15 —— 老客户端整体替换时不会被拒。
	AfterSaleDays   *int `json:"after_sale_days,omitempty"`
	AutoConfirmDays int  `json:"auto_confirm_days"`
	ReturnShipDays  int  `json:"return_ship_days"`

	// ServicePhone 客服电话。不给即清空
	ServicePhone *string `json:"service_phone,omitempty"`

	// Timezone IANA 时区名，如 `Asia/Shanghai`
	Timezone string `json:"timezone"`
}

// Sku defines model for Sku.
type Sku struct {
	AvailableQty int     `json:"available_qty"`
	Id           int64   `json:"id"`
	ImageUrl     *string `json:"image_url,omitempty"`

	// PriceCents 金额，单位「分」。禁止使用浮点。
	PriceCents Money `json:"price_cents"`

	// PromoPriceCents 这家门店此刻的活动价（限时折扣 / 秒杀，取 min(门店价, 特价)）。没有单价类活动、
	// 或特价不低于门店价时不出现。秒杀配额已售罄时不出现。
	PromoPriceCents *Money `json:"promo_price_cents,omitempty"`

	// PromotionId 给出 `promo_price_cents` 的那个活动。与 `promo_price_cents` 同进同出。
	PromotionId *int64 `json:"promotion_id,omitempty"`
	SkuCode     string `json:"sku_code"`

	// SpecValues Examples: {"尺码":"XL","颜色":"黑"}
	SpecValues *map[string]string `json:"spec_values,omitempty"`
}

// SkuCreateRequest `available_qty` 在这里是**允许的**，而在 `SkuUpdateRequest` 里不允许：
// 建行与改行是两件事——建的时候没有并发对手（这一行还不存在），
// 改的时候有（下单 SAGA 正在扣它）。
type SkuCreateRequest struct {
	// AvailableQty 初始库存。服务端在同一事务里建出 `inventories` 行，省略即 0。
	AvailableQty *int `json:"available_qty,omitempty"`

	// CostCents 金额，单位「分」。禁止使用浮点。
	CostCents *Money `json:"cost_cents,omitempty"`

	// ImageUploadId 该规格小图的 `uploads.id`，服务端据此写出 `skus.image_url`。
	// 与商品图同理：收 id 不收 URL。
	ImageUploadId *int64 `json:"image_upload_id,omitempty"`

	// PriceCents 金额，单位「分」。禁止使用浮点。
	PriceCents Money              `json:"price_cents"`
	SkuCode    string             `json:"sku_code"`
	SpecValues *map[string]string `json:"spec_values,omitempty"`

	// WarningQty 低库存预警线，省略即 0。
	WarningQty *int `json:"warning_qty,omitempty"`

	// WeightGram 重量（克），按重量计费的运费模板用它。省略即 0
	WeightGram *int `json:"weight_gram,omitempty"`
}

// SkuPriceSetRequest 设置本作用域的价格覆盖（upsert）。
// **不接受 `null`**——撤销覆盖走 `DELETE`，两个动作的语义不同：
// 设成 0 是「这家店免费送」，删掉是「这家店不要自己的价」。
type SkuPriceSetRequest struct {
	// PriceCents 本作用域的价，单位分，非负。
	PriceCents Money `json:"price_cents"`
}

// SkuUpdateRequest **刻意没有 `available_qty`**：库存有自己的端点，因为它要表达乐观并发。
// 见 `PUT /admin/skus/{sku_id}/inventory`。
type SkuUpdateRequest struct {
	// CostCents 金额，单位「分」。禁止使用浮点。
	CostCents     *Money `json:"cost_cents,omitempty"`
	ImageUploadId *int64 `json:"image_upload_id,omitempty"`

	// PriceCents 金额，单位「分」。禁止使用浮点。
	PriceCents *Money             `json:"price_cents,omitempty"`
	SkuCode    *string            `json:"sku_code,omitempty"`
	SpecValues *map[string]string `json:"spec_values,omitempty"`

	// Status 0 停售 / 1 在售
	Status *SkuUpdateRequestStatus `json:"status,omitempty"`

	// WeightGram 重量（克），按重量计费的运费模板用它
	WeightGram *int `json:"weight_gram,omitempty"`
}

// SkuUpdateRequestStatus 0 停售 / 1 在售
type SkuUpdateRequestStatus int

// Staff defines model for Staff.
type Staff struct {
	CreatedAt   time.Time           `json:"created_at"`
	Email       openapi_types.Email `json:"email"`
	Id          int64               `json:"id"`
	LastLoginAt *time.Time          `json:"last_login_at,omitempty"`

	// MerchantId 所属商家。**为 null 表示平台级操作员**——他不属于任何一家店，
	// 能建商家、做跨租户运维。
	MerchantId *int64  `json:"merchant_id"`
	Name       *string `json:"name,omitempty"`

	// RegionIds 管辖的大区（仅 role 3 非空）。按 id 升序
	RegionIds []int64 `json:"region_ids"`

	// Role 1 管理员 · 2 操作员 · 3 大区管理员 · 4 门店管理员
	//
	// 角色在各自层级内生效：平台级的管理员能加平台操作员、能开店；
	// 商家级的管理员只能加自己店的员工。3 / 4 只存在于商家级，
	// 各自带管辖范围（`Staff.region_ids` / `Staff.store_ids`，一个人可以管多个）。
	//
	// 同一租户内的权限矩阵（服务端逐条执行，界面上的置灰只是体验）：
	//
	// | 能做什么 | 1 | 2 | 3 | 4 |
	// |---|:-:|:-:|:-:|:-:|
	// | 商品、SKU、基准价、类目、上传、批量导入 | ✅ | ✅ | 只读 | 只读 |
	// | 运费模板：全店模板（建、改、删、设默认）；商品挂哪个模板随商品 | ✅ | ✅ | 只读 | 只读 |
	// | 运费模板：门店模板（建、改、删） | ✅ | ✅ | 本大区的门店 | 只限自己的门店 |
	// | 大区：改、删、大区价、大区上下架 | ✅ | ✅ | 只限自己的大区 | ❌ |
	// | 大区：建 | ✅ | ✅ | ❌ | ❌ |
	// | 门店：建、改、删、围栏 | ✅ | ✅ | 只限本大区的门店（换大区时新旧都得在范围内） | ❌ |
	// | 门店价、门店上下架、门店库存 | ✅ | ✅ | 本大区的门店 | 只限自己的门店 |
	// | 订单与售后：订单 / 退款单的列表与详情、发货、退款审核、确认收到退货 | ✅ | ✅ | 本大区的门店 | 只限自己的门店 |
	// | 经营报表：概览、趋势、商品排行、门店对比、库存预警（含两份 CSV 导出） | ✅ | ✅ | 本大区的门店 | 只限自己的门店 |
	// | 经营报表：搜索概况（检索日志没有门店维度） | ✅ | ✅ | ❌ | ❌ |
	// | 设默认门店（含建店时 is_default） | ✅ | ❌ | ❌ | ❌ |
	// | 店铺设置（时区、自动确认天数、退货寄回时限、客服电话）的读与改 | ✅ | ❌ | ❌ | ❌ |
	// | 员工管理 | ✅ | ❌ | 只能加、改本大区门店的门店管理员 | ❌ |
	// | 开店 | 仅平台级管理员 | | | |
	//
	// `PUT /admin/skus/{sku_id}/inventory`（商家恰好一家门店时的捷径）对 3 / 4
	// 只在那家店在范围内时放行。列表类接口对 3 / 4 只返回范围内的；
	// 订单与售后按订单的**履约门店**判，门店所属的大区取它**此刻**的大区
	// （货从哪家店出，就由管那家店库存的人处理这一单）；
	// 商品目录全量可读。被拒回 403，type 是 role-forbidden 或 out-of-scope。
	Role StaffRole `json:"role"`

	// Status 1 正常 2 停用
	Status StaffStatus `json:"status"`

	// StoreIds 管辖的门店（仅 role 4 非空）。按 id 升序
	StoreIds []int64 `json:"store_ids"`
}

// StaffStatus 1 正常 2 停用
type StaffStatus int

